const p=$input.first().json.body||$input.first().json;const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if(!uuid.test(String(p.meetingId||''))||!uuid.test(String(p.workflowRunId||'')))throw new Error('meetingId and workflowRunId must be UUIDs');
if(typeof p.transcript!=='string'||p.transcript.trim().length<20||p.transcript.length>150000)throw new Error('Transcript must contain 20..150000 characters');
if(!Array.isArray(p.attendeeIds)||p.attendeeIds.some(x=>!uuid.test(String(x))))throw new Error('attendeeIds must be an array of UUIDs');
return [{json:{meetingId:p.meetingId,workflowRunId:p.workflowRunId,transcript:p.transcript,attendeeIds:p.attendeeIds,meetingPurpose:String(p.meetingPurpose||'').slice(0,500),sourceType:p.sourceType||'MEETING_TRANSCRIPT',idempotencyKey:p.workflowRunId}}];

const p=$input.first().json;
let text=p.transcript.normalize('NFKC');
// Lightweight minimization only; backend remains authoritative for transcript privacy/redaction.
text=text.replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi,'[REDACTED_EMAIL]');
text=text.replace(/(?:\+?\d[\d .()\-]{7,}\d)/g,'[REDACTED_PHONE]');
text=text.replace(/\b(?:\d{3}-\d{2}-\d{4}|\d{9,12})\b/g,'[REDACTED_IDENTIFIER]');
if(text.length>120000)throw new Error('Redacted transcript exceeds AI context limit');
return [{json:{...p,redactedTranscript:text,redactionMode:'n8n_regex_minimization_v1'}}];

const input=$input.first().json;
const transcript=$node['HTTP Request: Save Redacted Meeting Transcript'].json;
const meetingResponse=$node['HTTP Request: Get CRM Attendee Context'].json;
const meeting=meetingResponse.data||meetingResponse;
const redactedTranscript=transcript.redactedTranscript;
if(typeof redactedTranscript!=='string'||redactedTranscript.trim().length<20)throw new Error('Backend-redacted transcript is missing');
const context={
  meeting:meeting.meeting||{},
  lead:meeting.lead?{
    companyName:meeting.lead.companyName||null,
    companyWebsite:meeting.lead.companyWebsite||null,
    jobTitle:meeting.lead.jobTitle||null
  }:null,
  customer:meeting.customer?{
    companyName:meeting.customer.companyName||null,
    companyWebsite:meeting.customer.companyWebsite||null,
    jobTitle:meeting.customer.jobTitle||null
  }:null,
  attendees:(meeting.attendees||[]).map(a=>({id:a.id,role:a.role})),
  transcriptId:transcript.id||transcript.data?.id||null,
  redactedTranscript,
  meetingPurpose:input.meetingPurpose
};
const prompt=\`Analyze this sales meeting transcript after backend PII minimization. Use only statements supported by the transcript and non-identifying CRM context. Do not invent commitments, owners, deadlines, prices or customer facts. Return JSON only: {"summary":"...","decisions":[{"text":"...","evidence":"..."}],"risks":[{"text":"...","evidence":"...","confidence":0.0}],"actionItems":[{"title":"...","description":"...","ownerAttendeeId":null,"dueDate":null,"evidence":"...","confidence":0.0,"requiresConfirmation":true}]}. If owner or due date was not explicit, use null and requiresConfirmation=true.
CONTEXT=\${JSON.stringify(context)}\`;
return [{json:{...input,context,prompt}}];

const ai=$input.first().json||{};const p=$node['Code: Build Meeting Prompt'].json;
const t=ai.candidates?.[0]?.content?.parts?.map(x=>x.text||'').join('')||'';if(!t)throw new Error('Gemini returned no meeting analysis');
const clean=t.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim();const result=JSON.parse(clean);
if(typeof result.summary!=='string'||!result.summary.trim())throw new Error('Meeting summary is required');
for(const k of ['decisions','risks','actionItems'])if(!Array.isArray(result[k]))throw new Error(k+' must be an array');
const attendees=new Set(p.attendeeIds);
const actionItems=result.actionItems.map(a=>({title:String(a.title||'').slice(0,200),description:String(a.description||'').slice(0,2000),ownerAttendeeId:a.ownerAttendeeId&&attendees.has(a.ownerAttendeeId)?a.ownerAttendeeId:null,dueDate:a.dueDate||null,evidence:String(a.evidence||'').slice(0,1000),confidence:typeof a.confidence==='number'?Math.min(1,Math.max(0,a.confidence)):0,requiresConfirmation:a.requiresConfirmation!==false,status:'PENDING_CONFIRMATION'}));
return [{json:{...p,meetingAnalysis:{summary:result.summary.slice(0,10000),decisions:result.decisions,risks:result.risks,actionItems},transcriptId:p.context.transcriptId}}];
